using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;
    vector<int> X(N);
    for (int i = 0; i < N; i++) {
        cin >> X[i];
    }
    sort(X.begin(), X.end());

    // Simulate two starting directions
    long long ans = 0;

    // Start clockwise
    {
        long long total = 0;
        int left = 0, right = N-1;
        int pos = 0;
        bool clockwise = true;
        while (left <= right) {
            if (clockwise) {
                int dist = (X[right] - pos + L) % L;
                total += dist;
                pos = X[right];
                right--;
            } else {
                int dist = (pos - X[left] + L) % L;
                total += dist;
                pos = X[left];
                left++;
            }
            clockwise = !clockwise;
        }
        ans = max(ans, total);
    }

    // Start counter-clockwise
    {
        long long total = 0;
        int left = 0, right = N-1;
        int pos = 0;
        bool clockwise = false;
        while (left <= right) {
            if (clockwise) {
                int dist = (X[right] - pos + L) % L;
                total += dist;
                pos = X[right];
                right--;
            } else {
                int dist = (pos - X[left] + L) % L;
                total += dist;
                pos = X[left];
                left++;
            }
            clockwise = !clockwise;
        }
        ans = max(ans, total);
    }

    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 L;
    cin >> N >> L;

    vector<int64> X(N);
    for (int i = 0; i < N; i++) cin >> X[i];
    sort(X.begin(), X.end());

    // Prefix sums of positions
    vector<int64> pref(N + 1, 0);
    for (int i = 0; i < N; i++) pref[i + 1] = pref[i] + X[i];

    // Y[i] = distance of X[i] from 0 in clockwise direction = L - X[i]
    vector<int64> Y(N);
    for (int i = 0; i < N; i++) Y[i] = L - X[i];

    // Prefix sums on reversed Y:
    // revY[k] = Y[N-1-k] = L - X[N-1-k]
    vector<int64> prefRevY(N + 1, 0);
    for (int k = 0; k < N; k++) {
        prefRevY[k + 1] = prefRevY[k] + (L - X[N - 1 - k]);
    }

    auto sumLeft = [&](int cnt) -> int64 {
        // sum of smallest cnt X's: X[0] ... X[cnt-1]
        return pref[cnt];
    };

    auto sumRightClock = [&](int cnt) -> int64 {
        // sum of clockwise distances of largest cnt X's:
        // (L-X[N-1]) + (L-X[N-2]) + ...
        return prefRevY[cnt];
    };

    int64 ans = 0;

    // Case 1:
    // Burn a trees on counter-clockwise side first (smallest coordinates),
    // b trees on clockwise side first (largest coordinates),
    // with a == b or a == b + 1.
    // Last move is to a left tree if a == b + 1, otherwise to a right tree.
    for (int a = 0; a <= N; a++) {
        // b = a
        {
            int b = a;
            if (a + b > N) break;
            int64 total = 2 * sumLeft(a) + 2 * sumRightClock(b);
            if (b > 0) total -= (L - X[N - b]); // last move to right counted once
            ans = max(ans, total);
        }
        // b = a - 1
        if (a >= 1) {
            int b = a - 1;
            if (a + b <= N) {
                int64 total = 2 * sumLeft(a) + 2 * sumRightClock(b);
                total -= X[a - 1]; // last move to left counted once
                ans = max(ans, total);
            }
        }
    }

    // Case 2: symmetric, swap left/right roles
    // Equivalent to considering clockwise-first structure.
    for (int b = 0; b <= N; b++) {
        // a = b
        {
            int a = b;
            if (a + b > N) break;
            int64 total = 2 * sumLeft(a) + 2 * sumRightClock(b);
            if (a > 0) total -= X[a - 1]; // last move to left counted once
            ans = max(ans, total);
        }
        // a = b - 1
        if (b >= 1) {
            int a = b - 1;
            if (a + b <= N) {
                int64 total = 2 * sumLeft(a) + 2 * sumRightClock(b);
                total -= (L - X[N - b]); // last move to right counted once
                ans = max(ans, total);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

