    static long[] a;
    static int N;
    static long L;
    static long[][][] dp;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        L = sc.nextLong();
        N = sc.nextInt();
        a = new long[N+2];
        for (int i = 1; i <= N; i++) a[i] = sc.nextLong();
        Arrays.sort(a, 1, N+1);
        dp = new long[N+2][N+2][2];
        for (long[][] x : dp) for (long[] y : x) Arrays.fill(y, -1);
        System.out.println(solve(1, N, 0));
    }

    // side=0: at a[l-1] (a[0]=0), side=1: at a[r+1] (a[N+1]=L, i.e., pos 0 from other side)
    static long solve(int l, int r, int side) {
        if (l > r) return 0;
        if (dp[l][r][side] != -1) return dp[l][r][side];
        long curPos = (side == 0) ? (l == 1 ? 0 : a[l-1]) : (r == N ? 0 : a[r+1]);
        // Go CW to a[l]: distance CW from curPos to a[l]
        long distCW = (a[l] - curPos + L) % L;
        // Go CCW to a[r]: distance CCW from curPos to a[r]
        long distCCW = (curPos - a[r] + L) % L;
        long res = Math.max(distCW + solve(l+1, r, 0), distCCW + solve(l, r-1, 1));
        dp[l][r][side] = res;
        return res;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt();
        int N = sc.nextInt();
        int[] X = new int[N];
        for (int i = 0; i < N; i++) {
            X[i] = sc.nextInt();
        }

        // dp[l][r][0] = max distance when we have burnt trees from l to r (clockwise interval)
        // and we are currently at left end (l)
        // dp[l][r][1] = same but at right end (r)
        long[][][] dp = new long[N][N][2];

        for (int len = 1; len <= N; len++) {
            for (int l = 0; l + len - 1 < N; l++) {
                int r = l + len - 1;
                if (len == 1) {
                    long distLeft = X[l];
                    long distRight = L - X[l];
                    dp[l][r][0] = Math.max(distLeft, distRight);
                    dp[l][r][1] = Math.max(distLeft, distRight);
                } else {
                    // from left end, go to next left or cross to right
                    long fromLeftGoLeft = dp[l+1][r][0] + (X[l+1] - X[l]);
                    long fromLeftGoRight = dp[l+1][r][1] + (L - (X[r] - X[l]));
                    dp[l][r][0] = Math.max(fromLeftGoLeft, fromLeftGoRight);

                    // from right end, go to next right or cross to left
                    long fromRightGoRight = dp[l][r-1][1] + (X[r] - X[r-1]);
                    long fromRightGoLeft = dp[l][r-1][0] + (X[r] - X[l] + (L - (X[r] - X[l])));
                    // Actually, from right end and going to leftmost unburnt:
                    long fromRightGoLeftCorrect = dp[l][r-1][0] + (X[r] - X[l] + (L - X[r] + X[l]));
                    // simpler: distance from X[r] to X[l] going counterclockwise = X[r] - X[l]
                    // but if we go clockwise from X[r] to X[l], it's L - (X[r] - X[l])
                    // Let's recalc properly:
                    // From right end at X[r], to reach X[l] clockwise: L - (X[r] - X[l])
                    // To reach X[l] counterclockwise: X[r] - X[l]
                    // Wait — we need the distance to the *other side* tree.
                    // From right end, the only unburnt tree on left is X[l].
                    // If we go counterclockwise, distance = X[r] - X[l].
                    // If we go clockwise, distance = L - (X[r] - X[l]).
                    // But we are already at right end, the next move could be to the leftmost unburnt.
                    // The DP transition from right end to leftmost: we first go to leftmost, so:
                    // Option: go clockwise to leftmost = L - (X[r] - X[l])
                    // Option: go counterclockwise to leftmost = X[r] - X[l]
                    // But after burning leftmost we are at l, and the remaining interval is [l, r-1] with position at l.
                    fromRightGoLeftCorrect = dp[l][r-1][0] + (X[r] - X[l]);
                    long fromRightGoRightCorrect = dp[l][r-1][1] + (L - (X[r] - X[l]));
                    dp[l][r][1] = Math.max(fromRightGoRightCorrect, fromRightGoLeftCorrect);
                }
            }
        }

        long answer = Math.max(dp[0][N-1][0], dp[0][N-1][1]);
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long L = fs.nextLong();
        long[] X = new long[N];
        for (int i = 0; i < N; i++) X[i] = fs.nextLong();
        Arrays.sort(X);

        // dpL[l][r][k]:
        // burnt trees are exactly [0..l-1] and [r+1..N-1], remaining are [l..r]
        // current position is:
        //   k=0 -> X[l-1] (last burnt on left side)
        //   k=1 -> X[r+1] (last burnt on right side)
        // value = maximum walked distance so far
        //
        // To avoid boundary issues, use virtual positions:
        // left virtual index -1 => coordinate 0
        // right virtual index N => coordinate 0 as well
        //
        // We process by number of remaining trees increasing backwards.

        long NEG = Long.MIN_VALUE / 4;
        long[][][] dp = new long[N + 1][N + 1][2];
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= N; j++) {
                dp[i][j][0] = dp[i][j][1] = NEG;
            }
        }

        // Initially remaining [0..N-1], position at 0.
        dp[0][N - 1][0] = 0;
        dp[0][N - 1][1] = 0;

        long ans = 0;

        for (int len = N; len >= 1; len--) {
            for (int l = 0; l + len - 1 < N; l++) {
                int r = l + len - 1;

                for (int side = 0; side < 2; side++) {
                    long cur = dp[l][r][side];
                    if (cur == NEG) continue;

                    long pos;
                    if (side == 0) {
                        pos = (l == 0 ? 0 : X[l - 1]);
                    } else {
                        pos = (r == N - 1 ? 0 : X[r + 1]);
                    }

                    // Go counter-clockwise to first remaining tree => left end l
                    long distCCW = (X[l] - pos + L) % L;
                    if (l == r) {
                        ans = Math.max(ans, cur + distCCW);
                    } else {
                        dp[l + 1][r][0] = Math.max(dp[l + 1][r][0], cur + distCCW);
                    }

                    // Go clockwise to first remaining tree => right end r
                    long distCW = (pos - X[r] + L) % L;
                    if (l == r) {
                        ans = Math.max(ans, cur + distCW);
                    } else {
                        dp[l][r - 1][1] = Math.max(dp[l][r - 1][1], cur + distCW);
                    }
                }
            }
        }

        System.out.println(ans);
    }
}

