#include <stdio.h>
#include <stdlib.h>

#define MAX_N 2000
#define MAX_L 1000000000

int n, L;
int x[MAX_N + 1];
long long dp[MAX_N + 1][MAX_N + 1][2];

long long max(long long a, long long b) {
    return a > b ? a : b;
}

int main() {
    scanf("%d %d", &n, &L);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &x[i]);
    }

    // dp[i][j][0] = max distance for burnt trees from i+1 to j-1, currently at i (clockwise side)
    // dp[i][j][1] = same but currently at j (counter-clockwise side)
    // i and j are indices in the tree array. We duplicate for circular handling.

    // We'll handle circular by extending the array: x[n+1]..x[2n] with x[i]+L
    for (int i = 1; i <= n; i++) {
        x[i + n] = x[i] + L;
    }

    int nn = 2 * n;
    for (int len = 1; len <= n; len++) {
        for (int i = 0; i + len <= nn; i++) {
            int j = i + len;
            if (len == 1) {
                dp[i][j][0] = 0;
                dp[i][j][1] = 0;
            } else {
                // from i to i+1..j-1 or j-1
                long long left0 = dp[i+1][j][0] + (x[i+1] - x[i]);
                long long left1 = dp[i+1][j][1] + (x[j] - x[i]);
                dp[i][j][0] = max(left0, left1);

                long long right0 = dp[i][j-1][0] + (x[j] - x[i]);
                long long right1 = dp[i][j-1][1] + (x[j] - x[j-1]);
                dp[i][j][1] = max(right0, right1);
            }
        }
    }

    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        ans = max(ans, dp[i][i+n][0]);
        ans = max(ans, dp[i][i+n][1]);
    }
    printf("%lld\n", ans);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int N;
    ll L;
    if (scanf("%d %lld", &N, &L) != 2) return 0;

    ll *X = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &X[i]);
    qsort(X, N, sizeof(ll), cmp_ll);

    /*
      DP on interval of already burnt trees in sorted order.

      Let trees be X[0..N-1] in CCW order.

      After some steps, burnt trees are exactly:
        X[0..l-1] and X[r+1..N-1]
      i.e. remaining trees are interval [l..r].

      Current position is either:
        left side  = X[l-1] (or 0 if l=0 and no left burnt tree exists initially only at start)
        right side = X[r+1]

      We maximize total walked distance from this state until all remaining trees are burnt.

      To avoid special handling of start, we define initial transitions from position 0
      to either X[0] (CCW) or X[N-1] (CW), then continue DP.

      dpL[l][r]: max additional distance from state with remaining [l..r], current pos = X[l-1]
      dpR[l][r]: max additional distance from state with remaining [l..r], current pos = X[r+1]

      Transition:
      From left position p = X[l-1]:
        burn leftmost remaining X[l]:
          dist = (X[l] - p + L) % L = X[l] - p
          next -> dpL[l+1][r] with current pos X[l]
        burn rightmost remaining X[r]:
          dist clockwise to first unburnt on that side = (p - X[r] + L) % L
          next -> dpR[l][r-1] with current pos X[r]

      From right position p = X[r+1]:
        burn leftmost remaining X[l]:
          dist counter-clockwise to first unburnt = (X[l] - p + L) % L
          next -> dpL[l+1][r]
        burn rightmost remaining X[r]:
          dist = (p - X[r] + L) % L = p - X[r]
          next -> dpR[l][r-1]

      Base: if l > r, 0.
    */

    ll **dpL = (ll **)malloc((N + 1) * sizeof(ll *));
    ll **dpR = (ll **)malloc((N + 1) * sizeof(ll *));
    for (int i = 0; i <= N; i++) {
        dpL[i] = (ll *)malloc((N + 1) * sizeof(ll));
        dpR[i] = (ll *)malloc((N + 1) * sizeof(ll));
        for (int j = 0; j <= N; j++) {
            dpL[i][j] = dpR[i][j] = 0;
        }
    }

    for (int len = 1; len <= N; len++) {
        for (int l = 0; l + len - 1 < N; l++) {
            int r = l + len - 1;

            // dpL[l][r], current position = X[l-1], valid only if l > 0
            if (l > 0) {
                ll p = X[l - 1];
                ll best = 0;

                // burn X[l]
                best = maxll(best, (X[l] - p) + dpL[l + 1][r]);

                // burn X[r]
                best = maxll(best, (p - X[r] + L) % L + dpR[l][r - 1]);

                dpL[l][r] = best;
            }

            // dpR[l][r], current position = X[r+1], valid only if r + 1 < N
            if (r + 1 < N) {
                ll p = X[r + 1];
                ll best = 0;

                // burn X[l]
                best = maxll(best, (X[l] - p + L) % L + dpL[l + 1][r]);

                // burn X[r]
                best = maxll(best, (p - X[r]) + dpR[l][r - 1]);

                dpR[l][r] = best;
            }
        }
    }

    ll ans = 0;

    // First move from 0 to X[0] counter-clockwise
    if (N >= 1) ans = maxll(ans, X[0] + (N >= 2 ? dpL[1][N - 1] : 0));

    // First move from 0 to X[N-1] clockwise
    if (N >= 1) ans = maxll(ans, (L - X[N - 1]) + (N >= 2 ? dpR[0][N - 2] : 0));

    printf("%lld\n", ans);

    for (int i = 0; i <= N; i++) {
        free(dpL[i]);
        free(dpR[i]);
    }
    free(dpL);
    free(dpR);
    free(X);
    return 0;
}
